func TestNovelVelocityBehavior(t *testing.T) {
	cases := []struct {
		name          string
		recent, prior int
		want          int
	}{
		{"doubling", 20, 10, 100},
		{"halving", 5, 10, -50},
		{"flat", 10, 10, 0},
		{"all new (no prior)", 8, 0, 100},
		{"empty", 0, 0, 0},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := growthPct(tc.recent, tc.prior); got != tc.want {
				t.Fatalf("growthPct(%d, %d) = %d, want %d", tc.recent, tc.prior, got, tc.want)
			}
		})
	}
}
